import type { LunghezzaParola } from './types';

// ============================================================================
// FILE GENERATO AUTOMATICAMENTE — non modificare a mano.
// Dizionario italiano (fonte di verità: tabella `words` su Supabase).
//   • SOLUZIONI = parole estraibili come bersaglio (is_solution = true)
//   • VALIDE    = tutte le parole accettate come tentativo valido
// Le parole sono già normalizzate (MAIUSCOLO, senza accenti).
//
// Per tenere il file compatto, ogni gruppo è UNA sola stringa: siccome tutte le
// parole di un gruppo hanno la stessa lunghezza fissa (5 o 6), si "ritagliano"
// a fette di quella misura con la funzione `taglia`.
//
// Conteggi:  soluzioni 5=1452  6=1705   valide 5=8176  6=18617
// ============================================================================

const SOL5 = '';
const SOL6 = '';
const VAL5 = '';
const VAL6 = '';

/** Ritaglia una stringa "compatta" in parole di lunghezza fissa `n`. */
function taglia(blob: string, n: number): string[] {
  const out: string[] = [];
  for (let i = 0; i < blob.length; i += n) out.push(blob.slice(i, i + n));
  return out;
}

/** Parole-bersaglio per lunghezza (da cui si pesca il target del single player). */
export const SOLUZIONI: Record<LunghezzaParola, string[]> = {
  5: taglia(SOL5, 5),
  6: taglia(SOL6, 6),
};

/** Insieme delle parole valide per lunghezza (per validare i tentativi). */
export const VALIDE: Record<LunghezzaParola, Set<string>> = {
  5: new Set(taglia(VAL5, 5)),
  6: new Set(taglia(VAL6, 6)),
};
